const {test}=require('node:test'),assert=require('node:assert/strict'),{createFocus}=require('../meteo-focus-core.js'),{preferences}=require('../meteo-core.js');
test('clock enlarges after inactivity and one wake restores the normal view with a fresh deadline',()=>{let now=0;const t=createFocus({now:()=>now});now=29999;assert.equal(t.tick(),false);now=30000;assert.equal(t.tick(),true);t.activity();assert.equal(t.expanded,true);t.wake();assert.equal(t.expanded,false);now=59999;assert.equal(t.tick(),false);now=60000;assert.equal(t.tick(),true)});
test('normal interactions postpone enlargement; settings and hidden weather view reset rather than accumulate idle time',()=>{let now=0;const t=createFocus({seconds:15,now:()=>now});now=14000;t.activity();now=15000;assert.equal(t.tick(),false);now=29000;assert.equal(t.tick(),true);now=60000;assert.equal(t.tick(true),false);now=74999;assert.equal(t.tick(),false);now=75000;assert.equal(t.tick(),true)});
test('disabled mode never enlarges and only supported presentation delays enter shared preferences',()=>{let now=0;const t=createFocus({seconds:0,now:()=>now});now=99999999;assert.equal(t.tick(),false);for(const focusSeconds of [0,15,30,60,120,300])assert.deepEqual(preferences({focusSeconds}),{focusSeconds});for(const focusSeconds of [-1,1,30.5,'30',true,Infinity]){assert.throws(()=>preferences({focusSeconds}));assert.throws(()=>createFocus({seconds:focusSeconds}))}assert.deepEqual(preferences({}),{})});
